    function SafeGetValue(obj, path, defaultValue = "--") {
        if (obj === undefined || obj === null) return defaultValue;
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
             if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        return current;
    }

    function updateProgressBar(barId, valueId, rawValue, min, max) {
        const bar = document.getElementById(barId);
        const valueDisplay = document.getElementById(valueId);
        if (!bar || !valueDisplay) return;

        let numericValue = parseFloat(rawValue);
        if (isNaN(numericValue)) numericValue = min;

        valueDisplay.innerText = rawValue;

        numericValue = Math.max(min, Math.min(max, numericValue));
        const percentage = ((numericValue - min) / (max - min)) * 100;
        bar.style.width = `${percentage}%`;
    }

