<script>
    // --- 数据填充和动态逻辑 ---
    function populateData() {
        // 这些占位符将由SillyTavern的正则表达式捕获组填充
        const worldInfo = "$1";
        const maleName = "$2";
        const maleDataStr = "$3";
        const femaleName = "$4";
        const femaleDataStr = "$5";
        const danmakuStr = "$6";
        const scStr = "$7";
        const pollStr = "$8";

        // --- 填充世界信息 ---
        document.getElementById('world-info').innerText = worldInfo;

        // --- 填充男方信息 ---
        const maleData = maleDataStr.split(';;');
        if (maleData.length >= 7) {
            document.getElementById('male-name').innerText = maleName;
            document.getElementById('male-location').innerText = maleData[0];
            document.getElementById('male-action').innerText = maleData[1];
            document.getElementById('male-outfit').innerText = maleData[2];
            const maleThoughtsEl = document.getElementById('male-thoughts');
            maleThoughtsEl.innerText = maleData[4];
            maleThoughtsEl.className = 'property-value'; // Reset class
            maleThoughtsEl.classList.add(`thought-${maleData[3]}`);
            document.getElementById('male-penis').innerText = maleData[5];
            document.getElementById('male-sex-history').innerText = maleData[6];
        }

        // --- 填充女方信息 ---
        const femaleData = femaleDataStr.split(';;');
        if (femaleData.length >= 11) {
            document.getElementById('female-name').innerText = femaleName;
            document.getElementById('female-location').innerText = femaleData[0];
            document.getElementById('female-action').innerText = femaleData[1];
            document.getElementById('female-outfit').innerText = femaleData[2];
            const femaleThoughtsEl = document.getElementById('female-thoughts');
            femaleThoughtsEl.innerText = femaleData[4];
            femaleThoughtsEl.className = 'property-value'; // Reset class
            femaleThoughtsEl.classList.add(`thought-${femaleData[3]}`);
            document.getElementById('female-vagina').innerText = femaleData[5];
            document.getElementById('female-breasts').innerText = femaleData[6];
            document.getElementById('female-anus').innerText = femaleData[7];
            document.getElementById('female-sex-history').innerText = femaleData[8];

            // 进度条
            const resistance = parseInt(femaleData[9], 10) || 0;
            const desire = parseInt(femaleData[10], 10) || 0;
            document.getElementById('female-resistance-value').innerText = `${resistance} / 100`;
            document.getElementById('female-resistance-bar').style.width = `${resistance}%`;
            document.getElementById('female-desire-value').innerText = `${desire} / 100`;
            document.getElementById('female-desire-bar').style.width = `${desire}%`;
        }

        // --- 填充互动页面 ---
        // 弹幕
        const danmakuContainer = document.getElementById('danmaku-container');
        danmakuContainer.innerHTML = ''; // 清空旧弹幕
        const danmakus = danmakuStr.split(';;');
        const colors = ['#FFD700', '#FF69B4', '#00BFFF', '#7FFF00', '#FF4500', '#9370DB'];
        danmakus.forEach((text, index) => {
            const danmakuEl = document.createElement('div');
            danmakuEl.className = 'danmaku';
            danmakuEl.innerText = text;
            danmakuEl.style.top = `${Math.random() * 85}%`;
            danmakuEl.style.color = colors[Math.floor(Math.random() * colors.length)];
            danmakuEl.style.animationDelay = `${index * 2.5}s`;
            danmakuContainer.appendChild(danmakuEl);
        });

        // SC挑战
        const scData = scStr.split(';;');
        const scAmount = parseFloat(scData[0].replace('¥', '')) || 0;
        if (scAmount > 0) {
            document.getElementById('sc-challenge').innerHTML = `<span>${scData[0]}</span><br><span style="font-size: 0.7em;">${scData[1]}</span>`;
        } else {
            document.getElementById('sc-challenge').innerText = '暂无SC挑战';
            document.getElementById('sc-challenge').style.animation = 'none'; // 没挑战就别闪了
        }

        // 投票
        const pollBody = document.getElementById('poll-body');
        pollBody.innerHTML = ''; // 清空旧投票
        if (pollStr.trim().toLowerCase() === '无') {
            pollBody.innerHTML = '<div class="poll-no-vote">当前无投票</div>';
        } else {
            const pollData = pollStr.split(';;');
            const pollTitle = pollData[0];
            document.querySelector('.poll-title').innerText = pollTitle;

            let options = [];
            let totalVotes = 0;
            for (let i = 1; i < pollData.length; i += 2) {
                const votes = parseInt(pollData[i+1], 10) || 0;
                options.push({ text: pollData[i], votes: votes });
                totalVotes += votes;
            }

            const pollColors = ['var(--accent-blue)', 'var(--accent-cyan)', 'var(--accent-orange)'];
            options.forEach((opt, index) => {
                const percentage = totalVotes > 0 ? ((opt.votes / totalVotes) * 100).toFixed(1) : 0;
                const optionEl = document.createElement('div');
                optionEl.className = 'poll-option';
                optionEl.innerHTML = `
                    <div class="poll-bar" style="width: ${percentage}%; background-color: ${pollColors[index % pollColors.length]};"></div>
                    <div class="poll-text-container">
                        <span>${opt.text}</span>
                        <span>${opt.votes}票 (${percentage}%)</span>
                    </div>
                `;
                pollBody.appendChild(optionEl);
            });
        }
    }

    // --- 控制逻辑 ---
    function toggleSection(headerElement) {
        headerElement.classList.toggle('collapsed');
        headerElement.nextElementSibling.style.display = headerElement.classList.contains('collapsed') ? 'none' : 'grid';
    }

    // --- 初始化 ---
    document.addEventListener('DOMContentLoaded', () => {
        // 填充数据
        populateData();

        // 初始化时所有区域默认折叠
        const headers = document.querySelectorAll('.section-header');
        headers.forEach(header => {
            header.classList.add('collapsed');
            header.nextElementSibling.style.display = 'none';
        });
    });

</script>

</body>
</html>
